/* Copy the LIVE public schema into the free mapstructor-test project.
 *
 * Why it works this way: there is no pg_dump, psql, Supabase CLI or Docker on this machine, and
 * the direct Postgres host is IPv6-only (down as often as not). So the schema is GENERATED by
 * asking live's catalog to describe itself, then REPLAYED through the Management API's query
 * endpoint on the test project. Both ends need nothing but the personal access token.
 *
 * Structure only — no rows. A practice database wants live's shape, not live's data.
 *
 *   node scripts/copy-schema-to-test.mjs --dry     print the statements, change nothing
 *   node scripts/copy-schema-to-test.mjs           apply them to mapstructor-test
 */
import fs from "node:fs";

const LIVE = "eqpxlwbjqiwfjlsuapvu";
const TEST = "odczsdvimfunmpkoakls";
const DRY = process.argv.includes("--dry");

const S = "c:/repos/mapstructor.github.io/secrets/";
let md = ""; for (const f of fs.readdirSync(S)) { try { md += fs.readFileSync(S + f, "utf8") + "\n"; } catch {} }
const PAT = (md.match(/sbp_[A-Za-z0-9]{40,}/) || [])[0];
if (!PAT) { console.error("no sbp_ personal access token in secrets/"); process.exit(1); }

async function sql(ref, query) {
  const r = await fetch(`https://api.supabase.com/v1/projects/${ref}/database/query`, {
    method: "POST",
    headers: { Authorization: `Bearer ${PAT}`, "Content-Type": "application/json" },
    body: JSON.stringify({ query }),
  });
  const t = await r.text();
  if (!r.ok) { const e = new Error(t.slice(0, 400)); e.http = r.status; throw e; }
  try { return JSON.parse(t); } catch { return []; }
}
const rowsOf = (list, key) => list.map((r) => r[key]).filter(Boolean);

/* spatial_ref_sys belongs to PostGIS and arrives with the extension */
const SKIP = `c.relname <> 'spatial_ref_sys'`;
/* an object owned by an extension is created BY that extension, never by us */
const NOT_EXT = (oid) => `not exists (select 1 from pg_depend d where d.objid = ${oid} and d.deptype='e')`;

/* ---- generation: each group is one dependency step, in the order Postgres needs ---- */
const GROUPS = [
  ["extensions", `
    select 'create extension if not exists '||quote_ident(extname)||' with schema '
           ||quote_ident(n.nspname)||';' as s
      from pg_extension e join pg_namespace n on n.oid = e.extnamespace
     where e.extname not in ('plpgsql')`],

  /* standalone sequences — a `serial` column's default calls nextval() on a sequence that
   * format_type() does not carry, so without this the table create fails outright */
  ["sequences", `
    select 'create sequence if not exists public.'||quote_ident(sequencename)
           ||' as '||data_type||' increment by '||increment_by
           ||' start with '||coalesce(start_value,1)||';' as s
      from pg_sequences where schemaname='public' order by sequencename`],

  ["tables", `
    with cols as (
      select c.relname, a.attnum,
             quote_ident(a.attname)||' '||format_type(a.atttypid, a.atttypmod)
             || case when a.attgenerated <> '' then ' generated always as ('||pg_get_expr(d.adbin,d.adrelid)||') stored'
                     when a.attidentity  <> '' then ' generated '||(case a.attidentity when 'a' then 'always' else 'by default' end)||' as identity'
                     when d.adbin is not null  then ' default '||pg_get_expr(d.adbin, d.adrelid)
                     else '' end
             || case when a.attnotnull and a.attgenerated = '' then ' not null' else '' end as coldef
        from pg_class c
        join pg_namespace n on n.oid = c.relnamespace
        join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
        left join pg_attrdef d on d.adrelid = c.oid and d.adnum = a.attnum
       where n.nspname = 'public' and c.relkind = 'r' and ${SKIP}
    )
    select 'create table if not exists public.'||quote_ident(relname)||' ('
           ||string_agg(coldef, ', ' order by attnum)||');' as s
      from cols group by relname order by relname`],

  /* primary keys and uniques first: foreign keys below need something to point at */
  ["keys+checks", `
    select 'alter table public.'||quote_ident(c.relname)||' add constraint '||quote_ident(con.conname)
           ||' '||pg_get_constraintdef(con.oid)||';' as s
      from pg_constraint con
      join pg_class c on c.oid = con.conrelid
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and con.contype in ('p','u','c') and ${SKIP}
     order by case con.contype when 'p' then 1 when 'u' then 2 else 3 end, c.relname`],

  ["functions", `
    select pg_get_functiondef(p.oid)||';' as s
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and ${NOT_EXT("p.oid")}
     order by p.proname`],

  ["foreign keys", `
    select 'alter table public.'||quote_ident(c.relname)||' add constraint '||quote_ident(con.conname)
           ||' '||pg_get_constraintdef(con.oid)||';' as s
      from pg_constraint con
      join pg_class c on c.oid = con.conrelid
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and con.contype = 'f' and ${SKIP}
     order by c.relname`],

  /* indexes that back a constraint were already made by the constraint */
  ["indexes", `
    select indexdef||';' as s
      from pg_indexes i
     where i.schemaname='public' and i.tablename <> 'spatial_ref_sys'
       and not exists (select 1 from pg_constraint c
                        where c.connamespace = 'public'::regnamespace and c.conname = i.indexname)
     order by i.tablename, i.indexname`],

  /* geometry_columns / geography_columns belong to PostGIS and arrive with it — recreating them
   * is refused ("must be owner of view"), correctly */
  ["views", `
    select 'create or replace view public.'||quote_ident(c.relname)||' as '||pg_get_viewdef(c.oid) as s
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and c.relkind='v' and ${NOT_EXT("c.oid")}
     order by c.relname`],

  ["triggers", `
    select pg_get_triggerdef(t.oid)||';' as s
      from pg_trigger t
      join pg_class c on c.oid = t.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and not t.tgisinternal and ${SKIP}
     order by c.relname`],

  ["row security", `
    select 'alter table public.'||quote_ident(c.relname)||' enable row level security;' as s
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname='public' and c.relkind='r' and c.relrowsecurity and ${SKIP}
     order by c.relname`],

  ["policies", `
    select 'create policy '||quote_ident(policyname)||' on public.'||quote_ident(tablename)
           ||' as '||permissive||' for '||cmd||' to '||array_to_string(roles, ', ')
           ||coalesce(' using ('||qual||')','')
           ||coalesce(' with check ('||with_check||')','')||';' as s
      from pg_policies where schemaname='public' order by tablename, policyname`],

  ["grants", `
    select 'grant '||string_agg(distinct privilege_type, ', ')||' on public.'||quote_ident(table_name)
           ||' to '||quote_ident(grantee)||';' as s
      from information_schema.role_table_grants
     where table_schema='public' and grantee in ('anon','authenticated','service_role')
       and table_name <> 'spatial_ref_sys'
     group by table_name, grantee order by table_name, grantee`],
];

/* ---- run ---- */
const plan = [];
for (const [name, gen] of GROUPS) {
  const stmts = rowsOf(await sql(LIVE, gen), "s");
  plan.push({ name, stmts });
  console.log(`${String(name).padEnd(14)} ${String(stmts.length).padStart(4)} statements`);
}
const total = plan.reduce((n, g) => n + g.stmts.length, 0);
console.log(`\n${total} statements generated from live.\n`);

if (DRY) {
  for (const g of plan) {
    console.log(`\n----- ${g.name} -----`);
    for (const s of g.stmts) console.log(s.length > 300 ? s.slice(0, 300) + " …" : s);
  }
  process.exit(0);
}

/* Apply one statement at a time so one failure never takes a whole group with it.
 * Several passes: a statement that failed only because its dependency had not been created yet
 * succeeds on the next lap. Stop when a pass fixes nothing. */
let pending = plan.flatMap((g) => g.stmts.map((s) => ({ g: g.name, s })));
let applied = 0, already = 0;
/* re-running this script must be safe, so "it is already there" counts as done, not as failure */
const BENIGN = /already exists|multiple primary keys/i;
for (let pass = 1; pass <= 4 && pending.length; pass++) {
  const failed = [];
  for (const item of pending) {
    try { await sql(TEST, item.s); applied++; }
    catch (e) {
      if (BENIGN.test(e.message)) { already++; continue; }
      failed.push({ ...item, err: String(e.message).slice(0, 200) });
    }
  }
  if (already) console.log(`  (${already} already present)`);
  console.log(`pass ${pass}: applied ${applied} · still failing ${failed.length}`);
  if (failed.length === pending.length) { pending = failed; break; }
  pending = failed;
}

console.log(`\nAPPLIED ${applied} of ${total}`);
if (pending.length) {
  console.log(`\nSTILL FAILING (${pending.length}) — each with its reason:`);
  for (const f of pending) console.log(`  [${f.g}] ${f.s.slice(0, 110)}\n      -> ${f.err}`);
}

/* proof grid: compare the two schemas object for object */
const PROOF = `
  select (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and c.relkind='r') tables,
         (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and c.relkind='v') views,
         (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
           where n.nspname='public' and not exists
             (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')) functions,
         (select count(*) from pg_policies where schemaname='public') policies,
         (select count(*) from pg_indexes where schemaname='public') indexes,
         (select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid
            join pg_namespace n on n.oid=c.relnamespace
           where n.nspname='public' and not t.tgisinternal) triggers`;
console.log("\n--- proof: live vs test ---");
console.log("live", JSON.stringify((await sql(LIVE, PROOF))[0]));
console.log("test", JSON.stringify((await sql(TEST, PROOF))[0]));
